UNIFY_HOST = "https://unify.apideck.com"
UPLOAD_HOST = "https://upload.apideck.com"
SERVICE_ID = "onedrive"
PAGE_SIZE = 3


class ApideckError(RuntimeError):
    pass


def require_env(name: str) -> str:
    value = os.environ.get(name)
